def get_document(kind, language="pt-BR"):
    language = language if language in LANGUAGES else "pt-BR"
    source = {"terms": TERMS, "privacy": PRIVACY}[kind]
    title = (paragraph("Termos de Uso", "Terms of Use", "Términos de Uso") if kind == "terms"
             else paragraph("Política de Privacidade", "Privacy Policy", "Política de Privacidad"))
    responsible = settings.OPENSCRIPT_LEGAL_RESPONSIBLE.strip()
    contact = settings.OPENSCRIPT_PRIVACY_EMAIL.strip()
    sections = [{"title": item["title"][language], "paragraphs": [p[language] for p in item["paragraphs"]]} for item in source]
    sections.append({
        "title": paragraph("Responsável e contato", "Responsible party and contact", "Responsable y contacto")[language],
        "paragraphs": [
            (paragraph("Responsável: {name}.", "Responsible party: {name}.", "Responsable: {name}.")[language].format(name=responsible)
             if responsible else paragraph("Nome do responsável: preencher depois.", "Responsible party's name: to be completed later.", "Nombre del responsable: completar después.")[language]),
            (paragraph("Contato de privacidade: {email}.", "Privacy contact: {email}.", "Contacto de privacidad: {email}.")[language].format(email=contact)
             if contact else paragraph("E-mail de contato: preencher depois. Informações de contato ainda não preenchidas nesta versão de teste.", "Contact email: to be completed later. Contact details have not yet been provided in this test version.", "Correo de contacto: completar después. Los datos de contacto aún no se han indicado en esta versión de pruebas.")[language]),
        ],
    })
    references = [] if kind == "terms" else [
        {"title": paragraph("Lei Geral de Proteção de Dados (LGPD)", "Brazil's General Data Protection Law (LGPD)", "Ley General de Protección de Datos de Brasil (LGPD)")[language],
         "url": "https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709compilado.htm"},
        {"title": paragraph("Privacidade do ngrok", "ngrok privacy", "Privacidad de ngrok")[language], "url": "https://ngrok.com/privacy"},
        {"title": paragraph("Termos do serviço ngrok", "ngrok service terms", "Términos del servicio ngrok")[language], "url": "https://ngrok.com/tos"},
        {"title": paragraph("Tratamento de dados pelo ngrok", "ngrok data processing", "Tratamiento de datos de ngrok")[language], "url": "https://ngrok.com/dpa"},
        {"title": paragraph("Privacidade do Google", "Google privacy", "Privacidad de Google")[language], "url": "https://policies.google.com/privacy"},
    ]
    return {"kind": kind, "title": title[language], "version": TERMS_VERSION if kind == "terms" else PRIVACY_VERSION,
            "updated_at": {"pt-BR": "12 de outubro de 2026", "en": "October 12, 2026", "es": "12 de octubre de 2026"}[language],
            "sections": sections, "language": language, "contact_pending": not bool(responsible and contact), "references": references}
